-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.priest.dps.Name"] = "伤害"
L["rm.era.priest.dps.Description"] = "1 至 60 级的伤害输出，也是治疗内置循环不适用时（单刷、暗影或尚未获得天赋）牧师的默认循环。学会后使用暗影形态；拉怪前单刷时先上护盾，然后是神圣之火（没有暗影形态时）、心灵震爆或惩击。对每个能存活较久的目标施放一次暗言术：痛，心灵震爆冷却完毕即用，精神鞭笞作为填充（学会前为惩击和神圣新星），单刷时对濒死目标或法力不足时使用魔杖。长时间战斗中使用吸血鬼的拥抱和噬灵瘟疫，团队副本中绝不使用。提醒：心灵之火、真言术：韧、种族增益、配合心灵震爆使用心灵专注、两个敌人贴近你且你生命值过半时使用心灵尖啸、目标转而攻击你时使用渐隐术、绝望祷言。目标选择、多目标持续伤害和降级施法由你自己掌控。"
L["rm.era.priest.dps.simulator.Name"] = "伤害（模拟器 亡灵团队）"
L["rm.era.priest.dps.simulator.Description"] = "推荐的伤害优先级，搭配 模拟器 为亡灵牧师做出的团队选择：心灵专注用于噬灵瘟疫而不是心灵震爆，并且在团队副本中也施放噬灵瘟疫，因此仅在你的团队还有空余减益效果栏位时使用它。不使用吸血鬼的拥抱。它是推荐的伤害内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.era.priest.dps.warcrafttavern.Name"] = "伤害（Warcraft Tavern 魔杖节能）"
L["rm.era.priest.dps.warcrafttavern.Description"] = "Warcraft Tavern 的低停顿升级打法，是推荐的伤害内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。单刷时：以心灵震爆拉怪，施放一次暗言术：痛，仅在目标生命值高于 30% 时再次使用心灵震爆，两次心灵震爆之间使用魔杖而不是惩击或精神鞭笞。拉怪前不会自动上护盾。组队时：暗言术：痛、心灵震爆、精神鞭笞。提醒与推荐的内置循环相同。"
L["rm.era.priest.healer.Name"] = "治疗者"
L["rm.era.priest.healer.Description"] = "组队且神圣或戒律是你的主天赋树时选用。治疗你选中的友方单位：低于 30% 时使用真言术：盾，低于 40% 时使用快速治疗，驱散，队伍中有三人受伤时使用治疗祷言，生命值低于一半时使用强效治疗术（学会前为治疗术或次级治疗术），移动时或伤害较轻时使用恢复，然后以 3 级治疗术作为高效补血。脱战时会建议对你的目标施放真言术：韧。选中敌人时提供暗言术：痛和惩击。提醒：心灵之火、真言术：韧、神圣之灵、心灵专注、绝望祷言；能量灌注默认关闭。治疗谁以及降级施法由你自己掌控。"
L["rm.forever.priest.dps.Name"] = "暗影和单刷伤害"
L["rm.forever.priest.dps.Description"] = "适用于 1 至 60 级的暗影以及所有牧师的单刷打法；永久服牧师的默认循环。以真言术：盾（单刷）和心灵震爆拉怪（神圣和戒律用神圣之火，学会心灵震爆前用惩击）。然后学会后使用暗影形态，你自己的暗言术：痛和噬灵瘟疫，心灵震爆，戒律用神圣之火接苦修，暗影形态下使用精神鞭笞；学会暗影形态前单刷时，神圣意志触发且有三个敌人时使用神圣新星，然后是魔杖（没有魔杖时用惩击）。移动时：痛、瘟疫。提醒：心灵之火、真言术：韧、神圣之灵、种族增益、吸血鬼的拥抱、心灵专注、沉默、艾露恩之光；心灵尖啸默认关闭。在永久服上生命值和法力值对插件隐藏，因此用暗言术：灭斩杀、治疗自己和黑暗献祭由你自己决定。基于 30 级测试版指南制作；暗影形态打法遵循 Mobalytics。"
L["rm.forever.priest.dps.mobalytics.Name"] = "持续伤害和魔杖升级（Mobalytics）"
L["rm.forever.priest.dps.mobalytics.Description"] = "Mobalytics 的升级打法，是推荐的暗影内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。心灵震爆和神圣之火只用于难缠的怪物（精英，或比你高两级），你自己的暗言术：痛和噬灵瘟疫，然后是魔杖（没有魔杖时用惩击）。学会暗影形态后：心灵震爆、痛、瘟疫、精神鞭笞。两次拉怪之间对自己使用真言术：盾和恢复，对自己使用祛病术。在永久服上生命值和法力值对插件隐藏，因此治疗自己由你自己决定。在多个怪物之间扩散痛由你决定。"
L["rm.forever.priest.healer.Name"] = "戒律和神圣治疗"
L["rm.forever.priest.healer.Description"] = "当戒律或神圣是你的主要天赋树且你未学会暗影形态后的团队治疗。治疗你当前的友方目标：拉怪前使用真言术：盾、愈合祷言和恢复；驱散魔法以及驱除疾病或祛病术；愈合祷言；神圣意志触发时使用神圣新星；苦修；缺失时使用恢复；治疗术（之前为次级治疗术）。目标为敌人时：暗言术：痛、神圣之火、苦修、惩击、魔杖。提醒：心灵之火、真言术：韧、神圣之灵、对其他玩家使用能量灌注、战斗中的心灵专注和种族法术。在永久服上生命值和法力值对插件隐藏，因此你选中的目标是判断谁需要治疗的唯一依据；紧急治疗、治疗祷言、联结治疗、强效治疗术和快速治疗、绝望祷言以及黑暗献祭由你自己决定。治疗谁和法术等级由你决定；学会苦修前的戒律治疗者（20–29 级）需要手动选择它。"
L["rm.mop.priest.discipline.Name"] = "推荐"
L["rm.mop.priest.discipline.Description"] = "戒律治疗，适用于 10 至 90 级，在戒律专精中选用。选中友方即可治疗：目标生命值较低时、拉怪前以及为了全神贯注大约每 12 秒使用真言术：盾；光明涌动触发时使用快速治疗；苦修；目标生命值很低时使用快速治疗；你们两人都受伤时使用联结治疗；愈合祷言；三名盟友受伤时使用治疗祷言和你的第六层天赋；强效治疗术；移动时使用恢复；用治疗术补满。灵魂护壳期间建议使用治疗祷言或强效治疗术。选中敌人即可通过救赎进行治疗：苦修、真言术：慰或神圣之火、对怪群使用你的第六层天赋、单刷时使用暗言术：痛、惩击。提醒：心灵之火、真言术：韧、福音传播达到五层时使用天使长、心灵专注、对濒死目标使用痛苦压制、为法力使用暗影魔或摧心魔、能量灌注、绝望祷言。由你自己掌控：治疗谁、灵魂护壳的时机（可开启的提醒）、真言术：障、虚空转移以及坦克身上的恩赐层数。"
L["rm.mop.priest.holy.Name"] = "推荐"
L["rm.mop.priest.holy.Description"] = "神圣治疗，适用于 10 至 90 级，在神圣专精中选用。选中友方即可治疗：脉轮：静状态下使用圣言术：静；仅在目标即将死亡时使用真言术：盾；光明涌动触发时使用快速治疗；愈合祷言；生命值很低时使用快速治疗；你们两人都受伤时使用联结治疗；组队且三名盟友受伤时，使用治疗之环、脉轮：佑状态下的圣言术：佑、你的第六层天赋和治疗祷言；恢复；生命值低或妙手回春达到两层时使用强效治疗术；治疗术。选中敌人即可造成伤害：圣言术：罚、真言术：慰或神圣之火、单刷时使用暗言术：痛、对怪群使用你的第六层天赋、惩击。没有脉轮时会为你选择一个（团队中为佑，小队中为静，单刷时为罚），且绝不切换。提醒：心灵之火、真言术：韧、对濒死目标使用守护之魂、五名盟友严重受伤时使用神圣赞美诗、为法力使用暗影魔或摧心魔、能量灌注、绝望祷言。由你自己掌控：治疗谁、圣言术：佑的放置、光明之泉和虚空转移。"
L["rm.mop.priest.holy.icyveins.Name"] = "紧急治疗放最后（Icy Veins）"
L["rm.mop.priest.holy.icyveins.Description"] = "默认关闭。Icy Veins 的神圣顺序，按你的脉轮选择。脉轮：佑状态下：三名盟友受伤时使用圣言术：佑，恢复，治疗之环，愈合祷言，治疗祷言，然后仅在紧急时使用联结治疗和快速治疗。其他情况：恢复，圣言术：静，愈合祷言，强效治疗术，治疗术，联结治疗，快速治疗，最后是真言术：盾，学会治疗术之前以快速治疗作为填充。切换、提醒和伤害列表与推荐的神圣内置循环相同；启用它并禁用那个即可使用。"
L["rm.mop.priest.shadow.Name"] = "推荐"
L["rm.mop.priest.shadow.Description"] = "暗影伤害，适用于 10 至 90 级，在暗影专精中选用。以心灵尖刺、心灵震爆或你的持续伤害效果开场。三颗暗影宝珠时使用噬灵疫病（心灵震爆已就绪或还要六秒以上才就绪时），心灵震爆，目标生命值低于 20% 时使用暗言术：灭，如果你选了慰与乱，则在你的噬灵疫病生效期间使用精神鞭笞，对能存活较久的目标在接近结束时刷新暗言术：痛和吸血鬼之触，黑暗涌动触发时使用心灵尖刺，在最佳距离使用光晕、瀑流或神圣之星，然后是精神鞭笞。精神鞭笞会为心灵震爆或暗言术：灭提前打断，或在第二次伤害之后打断；其他引导法术绝不打断。移动时只建议瞬发法术。五个或更多敌人时：你的第六层天赋、对你的目标施放持续伤害效果以及精神灼烧。提醒：暗影形态、心灵之火、真言术：韧、对可打断的施法使用沉默、长时间战斗中使用暗影魔或摧心魔以及能量灌注、吸血鬼的拥抱、生命值低时使用绝望祷言和消散。由你自己掌控：对其他目标施放持续伤害效果以及精神灼烧的落点。"
L["rm.mop.priest.shadow.warcrafttavern.Name"] = "不优先疯狂（Warcraft Tavern）"
L["rm.mop.priest.shadow.warcrafttavern.Description"] = "默认关闭。Warcraft Tavern 的暗影顺序：三颗暗影宝珠时使用噬灵疫病，低于 20% 时使用暗言术：灭，心灵震爆，吸血鬼之触，暗言术：痛，黑暗涌动触发时使用心灵尖刺，你的第六层天赋，精神鞭笞。与推荐的暗影内置循环不同，它绝不会在噬灵疫病期间提前精神鞭笞，也不会为心灵震爆保留噬灵疫病。开场、移动、怪群和提醒步骤相同；启用它并禁用推荐的循环即可使用。"
L["rm.mop.priest.unspecialized.Name"] = "无专精"
L["rm.mop.priest.unspecialized.Description"] = "适用于 1 至 9 级，或尚未选择专精的牧师。敌人：目标能存活足够久时使用暗言术：痛，然后是惩击。友方：目标生命值低时使用快速治疗，否则使用真言术：盾。提醒：心灵之火，以及单刷受伤时对自己施放护盾。10 级选择专精后会切换到该专精自己的内置循环。"
L["rm.retail.priest.discipline.Name"] = "救赎（Icy Veins）"
L["rm.retail.priest.discipline.Description"] = "至暗之夜的戒律专精，仅供参考：暴雪的战斗辅助不涵盖治疗者，游戏在战斗中会隐藏所有人的生命值，而 Rotation Master 选择的是法术而不是目标，因此它会打出通过救赎转化为治疗的伤害，决定治疗谁则交给你。友方目标：真言术：盾（虚空之盾），苦修，快速治疗。敌人：12 秒内未施放过暗言术：痛时使用暗言术：痛，心灵震爆，苦修，真言术：盾，暗言术：灭，虚空冲击，惩击。战斗中的提醒：真言术：耀、福音、终极苦修、对友方目标使用痛苦压制；拉怪间隙的真言术：韧。绝望祷言由你自己决定。大伤害到来前为团队铺救赎的时机由你自己掌握。"
L["rm.retail.priest.discipline.wowhead.Name"] = "暗言术：灭优先参考（Wowhead）"
L["rm.retail.priest.discipline.wowhead.Description"] = "仅供参考，默认关闭：Wowhead 的第 1 赛季神谕者施放顺序，通过读取减益效果来维持暗言术：痛，而至暗之夜会在战斗中隐藏该减益效果。暗言术：痛，暗言术：灭冷却好就用，苦修，心灵震爆，惩击；友方目标时优先使用苦修。提醒与 Icy Veins 内置循环相同。"
L["rm.retail.priest.holy.Name"] = "Icy Veins"
L["rm.retail.priest.holy.Description"] = "至暗之夜的神圣专精，仅供参考：游戏在战斗中会隐藏所有人的生命值，而 Rotation Master 选择的是法术而不是目标，因此它会针对你当前的目标让圣言术、愈合祷言和触发效果持续运转，治疗分配则交给你。友方目标：圣言术：灵，圣言术：静，愈合祷言，圣光涌动触发时使用治疗祷言，祈福，织光者触发时使用治疗祷言，圣光涌动触发时使用快速治疗，在队伍中使用治疗祷言，移动中使用神圣新星，快速治疗。敌人：圣言术：罚，神圣之火，移动中使用神圣新星，惩击。提醒：战斗中的神圣化身、神圣赞美诗和光晕、对友方目标使用守护之魂（生命值在正式服中是隐藏的，因此目标是否即将死亡由你自己判断）、真言术：韧。绝望祷言由你自己决定。"
L["rm.retail.priest.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.priest.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是牧师的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有牧师内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.priest.shadow.Name"] = "暴雪战斗辅助"
L["rm.retail.priest.shadow.Description"] = "推荐至暗之夜的暗影专精使用。在战斗中，游戏现在会对插件隐藏你的持续伤害效果、增益效果、冷却时间和生命值，因此它会显示暴雪自己的战斗辅助建议（一键循环，它会维持你的持续伤害效果、暗影形态和虚空形态，并让精神鞭笞引导完成），并在你施法或没有选中敌人时停止。提醒它未包含的内容：施放虚空形态后的 20 秒内使用能量灌注、拉怪间隙的暗影形态和真言术：韧、对可打断的施法使用沉默（只在游戏允许读取该施法的场合亮起）。生命值在正式服中是隐藏的，因此绝望祷言由你自己决定。"
L["rm.retail.priest.shadow.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.priest.shadow.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft 的施放顺序需要读取持续伤害效果的计时、疯狂和虚空形态，而至暗之夜会在战斗中隐藏它们；狂乱值和生命值在正式服中是隐藏的，所以狂乱值溢出前的暗言术：癫、暗言术：灭斩杀和绝望祷言由你自己决定。拉怪前使用吸血鬼之触；用触须猛击施加吸血鬼之触；吸血鬼之触和暗言术：痛在剩余最后 30% 时刷新；暗言术：癫即将结束或在虚空形态期间时使用暗言术：癫；疯狂期间使用虚空冲击；两层充能时使用触须猛击；虚空洪流；心灵震爆；触须猛击；疯狂期间使用精神鞭笞：狂；虚空齐射；移动中使用暗言术：灭和暗言术：痛；精神鞭笞，心灵震爆就绪时中断引导。提醒：光晕、两个持续伤害效果都生效时使用虚空形态、虚空形态期间使用能量灌注。"
L["rm.sod.priest.dps.Name"] = "伤害（探索赛季）"
L["rm.sod.priest.dps.Description"] = "探索赛季服务器上的伤害输出，适用于 1 至 60 级，使用你已铭刻的符文。暗影形态；以吸血鬼之触或心灵震爆拉怪（暗影形态之前为苦修、神圣之火或惩击）。保持虚空疫病、暗言术：痛和吸血鬼之触（只有在未铭刻痛苦与折磨时才在接近结束时刷新），心灵震爆冷却完毕即用，熔化面容时使用精神鞭笞，你的生命值高于一半时使用暗言术：灭，然后以心灵尖刺作为填充，拥有第 8 阶段六件套时改用精神鞭笞。四个或更多敌人时使用虚空领域和精神灼烧。单刷时对濒死目标使用魔杖。提醒：心灵之火、真言术：韧、裂魂魔、暗影魔、虚空之眼和消散、心灵专注、心灵尖啸、渐隐术、绝望祷言。"
L["rm.sod.priest.dps.wowhead.Name"] = "伤害（探索赛季，Wowhead 心灵尖刺叠层）"
L["rm.sod.priest.dps.wowhead.Description"] = "Wowhead 和 Warcraft Tavern 的探索赛季打法，是推荐的探索赛季伤害内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。心灵震爆会等到目标身上有你的三层心灵尖刺（铭刻心灵尖刺之前正常施放），精神鞭笞仅在熔化面容时使用，心灵尖刺作为填充。其余与推荐的内置循环相同。"
L["rm.sod.priest.healer.Name"] = "治疗（探索赛季）"
L["rm.sod.priest.healer.Description"] = "在探索赛季服务器上组队且神圣或戒律是你的主天赋树时选用；遵循 Icy Veins。治疗你选中的友方单位：拉怪前以及就绪时使用愈合祷言，生命值低于一半时使用真言术：盾，苦修，圣光涌动触发时使用瞬发快速治疗，紧急时使用快速治疗，驱散，队伍中有三人受伤时使用治疗之环和治疗祷言，生命值低于一半时使用强效治疗术，移动时或伤害较轻时使用恢复，然后是治疗术。选中敌人时提供暗言术：痛、虚空疫病、苦修、神圣之火和惩击。提醒包括暗影魔、对濒死目标使用痛苦压制、队伍受伤时使用真言术：障和救赎者之魂。"
L["rm.sod.priest.healer.warcrafttavern.Name"] = "治疗（探索赛季，Warcraft Tavern）"
L["rm.sod.priest.healer.warcrafttavern.Description"] = "Warcraft Tavern 的妙手回春循环，专为妙手回春和灵魂守护设计，是推荐的探索赛季治疗内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。愈合祷言冷却完毕即用，只要你的目标能承受就对其施放真言术：盾（铭刻了灵魂守护时；否则在生命值低于一半时），伤害较重时使用苦修，三人受伤时使用治疗之环，妙手回春达到三层时使用强效治疗术或治疗祷言，伤害较轻时使用恢复，轻伤时使用快速治疗来叠层（铭刻了妙手回春时；否则在低于 30% 时）。"
L["rm.tbc.priest.dps.icyveins.Name"] = "伤害（Icy Veins）"
L["rm.tbc.priest.dps.icyveins.Description"] = "1 至 70 级的伤害输出，只要治疗内置循环不适用就会使用。前期使用惩击和魔杖，然后随着学会依次加入心灵震爆、暗言术：痛、精神鞭笞、暗影形态、吸血鬼之触和暗言术：灭；心灵震爆之前先上持续伤害效果；单刷时对濒死目标使用魔杖。神圣和戒律的任务玩家使用神圣之火和惩击。提醒：心灵之火、真言术：韧、种族增益、心灵专注、暗影恶魔。精神鞭笞在第一跳之后，会为已就绪的心灵震爆而被提前打断，或在生命值高于一半时为暗言术：灭而被提前打断。护盾和治疗由你自己掌控。"
L["rm.tbc.priest.dps.wowhead.Name"] = "伤害（Wowhead）"
L["rm.tbc.priest.dps.wowhead.Description"] = "依据 Wowhead 指南的伤害输出，是推荐的 Icy Veins 伤害内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。以心灵震爆开怪，并优先于刷新持续伤害效果，仅在生命值下降时使用吸血鬼的拥抱，对濒死目标使用法术而非魔杖。其余与推荐的内置循环相同。"
L["rm.tbc.priest.healer.icyveins.Name"] = "治疗（Icy Veins）"
L["rm.tbc.priest.healer.icyveins.Description"] = "依据 Icy Veins 顺序的治疗：真言术：盾、驱散、联结治疗、恢复、快速治疗、强效治疗术（任意等级）、群体治疗，最后是愈合祷言。治疗谁由你决定。它是推荐的 Wowhead 治疗内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.tbc.priest.healer.wowhead.Name"] = "治疗（Wowhead）"
L["rm.tbc.priest.healer.wowhead.Description"] = "神圣或戒律是你的主天赋树时的队伍治疗。它针对你选中的友方单位提供建议；治疗谁由你决定。拉怪前以及就绪时使用愈合祷言，恢复，紧急时使用真言术：盾，驱散，队伍受伤时使用治疗之环或治疗祷言，联结治疗、快速治疗和强效治疗术，并以 1 级强效治疗术作为低耗补血。选中敌人时会提供少量伤害技能。"
